import { Field } from "./Field";
export class Validator extends Field {
    constructor(config) {
        super(config);
    }
    declareData(...args) {
        return super.declareData(...args, {
            value: {
                structured: true,
            },
            disabled: undefined,
        });
    }
    isEmpty(data) {
        return false;
    }
    render(context, instance, key) {
        if (!instance.state?.visited || !instance.data.error)
            return null;
        return this.renderChildren(context, instance, key);
    }
}
